<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class ProductCatalog {
 public static function register(): void { add_shortcode('avanik_product_catalog',[self::class,'render']); }
 public static function render(): string { global $wpdb; $type=sanitize_key(wp_unslash($_GET['product_type']??'')); $dest=sanitize_text_field(wp_unslash($_GET['destination']??'')); $sql='SELECT * FROM '.ProductRepository::table_name().' WHERE status=%s'; $args=[Product::PUBLISHED]; if($type){$sql.=' AND type=%s';$args[]=$type;} if($dest){$sql.=' AND metadata LIKE %s';$args[]='%'. $wpdb->esc_like($dest) .'%';} $sql.=' ORDER BY published_at DESC, id DESC'; $rows=$wpdb->get_results($wpdb->prepare($sql,...$args),ARRAY_A)?:[]; ob_start(); ?><section class="avanik-product-catalog" dir="rtl"><h2>محصولات آوانیک</h2><form method="get"><input name="destination" placeholder="مقصد" value="<?php echo esc_attr($dest); ?>"><select name="product_type"><option value="">همه</option><?php foreach(['tour'=>'تور','hotel'=>'هتل','flight'=>'پرواز','package'=>'پکیج'] as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($type,$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select><button>جستجو</button></form><div class="avanik-products"><?php foreach($rows as $r): $m=json_decode((string)$r['metadata'],true)?:[]; ?><article><h3><?php echo esc_html($r['title']); ?></h3><p><?php echo esc_html($r['type']); ?> — <?php echo esc_html($r['price'].' '.$r['currency']); ?></p><p><?php echo esc_html($m['destination']??''); ?></p><p><?php echo esc_html($m['description']??''); ?></p><p>ظرفیت: <?php echo esc_html($r['capacity']); ?></p></article><?php endforeach; if(!$rows): ?><p>محصولی پیدا نشد.</p><?php endif; ?></div></section><?php return (string)ob_get_clean(); }
}